<script lang="ts">
import type{Snippet}from"svelte";import{onMount}from"svelte";import{page}from"$app/state";import{onNavigate}from"$app/navigation";import"../../../shared/prisma.css";
let{children}=$props<{children:Snippet}>();let theme=$state<"obsidiana"|"cuarzo">("obsidiana");let dialog:HTMLDialogElement;let swState=$state("Comprobando Service Worker…");let heap=$state("Memoria: no expuesta");let promptEvent=$state<any>(null);
function setTheme(value:"obsidiana"|"cuarzo"){theme=value;document.documentElement.dataset.theme=value;localStorage.setItem("prisma-fw-theme",value);}
onMount(()=>{const saved=localStorage.getItem("prisma-fw-theme");if(saved==="cuarzo"||saved==="obsidiana")setTheme(saved);else document.documentElement.dataset.theme=theme;const open=()=>dialog?.showModal();const install=(event:Event)=>{event.preventDefault();promptEvent=event;};window.addEventListener("prisma:settings",open);window.addEventListener("beforeinstallprompt",install);if("serviceWorker"in navigator)navigator.serviceWorker.ready.then(()=>swState=navigator.serviceWorker.controller?"Service Worker controla esta pestaña":"Registrado; recarga para activar el control").catch(()=>swState="No disponible");else swState="No disponible";const memory=(performance as any).memory;if(memory)heap=(memory.usedJSHeapSize/1048576).toFixed(1)+" MB de heap JS";return()=>{window.removeEventListener("prisma:settings",open);window.removeEventListener("beforeinstallprompt",install);};});
onNavigate((navigation)=>{if(!document.startViewTransition)return;return new Promise<void>(resolve=>{document.startViewTransition(async()=>{resolve();await navigation.complete;});});});
async function installApp(){if(!promptEvent)return;await promptEvent.prompt();await promptEvent.userChoice;promptEvent=null;}
</script>
{@render children()}
{#if !page.url.pathname.startsWith("/pelicula/")}
<nav class="nav" aria-label="Navegación principal"><a href="/personal" aria-current={page.url.pathname==="/personal"?"page":undefined}><i aria-hidden="true">◉</i>Personal</a><a href="/" aria-current={page.url.pathname!=="/personal"?"page":undefined}><i aria-hidden="true">✧</i>Descubrir</a></nav>
{/if}
<dialog class="dialog" bind:this={dialog} aria-labelledby="settings-title"><h2 id="settings-title">Ajustes de la prueba</h2><p>Solo datos ficticios. Sin TMDB, SQLite ni diarios personales.</p><p>Tema visual</p><div class="row"><button class="btn" aria-pressed={theme==="obsidiana"} onclick={()=>setTheme("obsidiana")}>Obsidiana</button><button class="btn" aria-pressed={theme==="cuarzo"} onclick={()=>setTheme("cuarzo")}>Cuarzo</button></div><section class="section"><strong>Estado PWA</strong><p>{swState}</p><p>{heap}</p>{#if promptEvent}<button class="btn primary" onclick={installApp}>Instalar muestra</button>{:else}<p>Instalación: depende de la oferta del navegador.</p>{/if}</section><div class="row"><button class="btn" onclick={()=>dialog.close()}>Cerrar</button></div></dialog>